// relaySeededPlan is the plan a seeded relay job carries: every PlanSpec
// field populated, so the wire assertion proves each descriptor field
// verbatim — including body ([]byte → the base64 string the SPA executes)
// and the binary_safe flag that governs that encoding.
var relaySeededPlan = []store.PlanSpec{
	{
		Method:         "GET",
		URL:            "https://api.example.org/3/search/tv?query=aria",
		Headers:        map[string]string{"Authorization": "Bearer relay-secret"},
		Body:           []byte{0x00, 0xff, 0x10},
		BinarySafe:     true,
		TimeoutSeconds: 7,
		MinIntervalMS:  250,
	},
	{
		Method:         "POST",
		URL:            "https://api.example.org/3/tv/378",
		Body:           []byte(`{"watch_region":"RU"}`),
		BinarySafe:     false,
		TimeoutSeconds: 5,
		MinIntervalMS:  100,
	},
}

// seedRelayJob inserts one pending enrich job with relaySeededPlan and
// returns its minted id.
func seedRelayJob(t *testing.T, st *store.Store) int64 {
	t.Helper()
	id, err := st.CreateRelayJob(context.Background(), store.RelayJob{
		Purpose:   "enrich",
		RowID:     "itm_relay",
		LibraryID: 3,
		PluginID:  "tmdb",
		Plan:      relaySeededPlan,
	})
	if err != nil {
		t.Fatalf("CreateRelayJob: %v", err)
	}
	return id
}

// relayClaimCalls records one Deps.RelayClaim invocation's principal hash.
var relayClaimCalls []string

// relayClaimClosure is the cmd/mellifera closure's exact delegation shape
// (task 4.3): the enrich Relay.Claim forwards to the store's ONE conditional
// UPDATE with the clock and lease the composition root owns — the test builds
// it straight over the store seam, one hop down, and records every principal
// hash it is called with.
func relayClaimClosure(st *store.Store) func(context.Context, string) (store.RelayJob, bool, error) {
	return func(ctx context.Context, principalHash string) (store.RelayJob, bool, error) {
		relayClaimCalls = append(relayClaimCalls, principalHash)
		now := time.Now()
		return st.ClaimOldestRelayJob(ctx, principalHash, now, now.Add(2*time.Minute))
	}
}

// relayHashToken is the assertion-side mirror of the api's principalHash: the
// SHA-256 hex of a credential — the pairing hashToken recipe (INV3).
func relayHashToken(raw string) string {
	sum := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(sum[:])
}

// TestRelayClaim pins the POST /api/v1/relay/claim wire contract (client-
// relayed-fetch 4.1): 200 carrying the descriptor verbatim from the seeded
// store row (id, purpose, the plan with body as a base64 string), the claim
// stamped with the SHA-256 hex of the presented credential (the pairing
// hashToken recipe — the SAME identity the result route's guard re-derives),
// a live lease held by one principal hides the row from the next (single
// claimant), 503 when the closure is nil, 500 on a real closure failure, 401
// unauthenticated with the closure never called, and the browse-group role
// posture: a paired device token reaches the handler, an injected unknown
// role is 403.
func TestRelayClaim(t *testing.T) {
	path := "/api/v1/relay/claim"

	t.Run("descriptor_fields_verbatim_from_a_seeded_job", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		relayClaimCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayClaim: relayClaimClosure(st)})

		resp := doRequest(t, h, http.MethodPost, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		// The raw wire shape first: body must read back as the base64 string
		// encoding/json emits for []byte — the SPA executes this field.
		var raw struct {
			ID      int64  `json:"id"`
			Purpose string `json:"purpose"`
			Plan    []struct {
				Method         string            `json:"method"`
				URL            string            `json:"url"`
				Headers        map[string]string `json:"headers"`
				Body           string            `json:"body"`
				BinarySafe     bool              `json:"binary_safe"`
				TimeoutSeconds int               `json:"timeout_seconds"`
				MinIntervalMS  int               `json:"min_interval_ms"`
			} `json:"plan"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&raw); err != nil {
			t.Fatalf("decode descriptor: %v", err)
		}
		if raw.ID != wantID || raw.Purpose != "enrich" {
			t.Fatalf("descriptor id/purpose = %d/%q, want %d/enrich", raw.ID, raw.Purpose, wantID)
		}
		if len(raw.Plan) != len(relaySeededPlan) {
			t.Fatalf("plan length = %d, want %d", len(raw.Plan), len(relaySeededPlan))
		}
		wantB64 := base64.StdEncoding.EncodeToString(relaySeededPlan[0].Body)
		if raw.Plan[0].Body != wantB64 {
			t.Fatalf("plan[0].body = %q, want base64 %q", raw.Plan[0].Body, wantB64)
		}
		if raw.Plan[0].BinarySafe != true || raw.Plan[1].BinarySafe != false {
			t.Fatalf("binary_safe flags = %v/%v, want true/false", raw.Plan[0].BinarySafe, raw.Plan[1].BinarySafe)
		}
		if raw.Plan[0].Headers["Authorization"] != relaySeededPlan[0].Headers["Authorization"] {
			t.Fatalf("plan[0].headers = %v, want the seeded map verbatim", raw.Plan[0].Headers)
		}
		if raw.Plan[0].TimeoutSeconds != 7 || raw.Plan[0].MinIntervalMS != 250 {
			t.Fatalf("plan[0] timing = %d/%d, want 7/250", raw.Plan[0].TimeoutSeconds, raw.Plan[0].MinIntervalMS)
		}
		// The identity source: the claim was stamped with the SHA-256 hex of
		// the presented credential — the pairing hashToken recipe.
		if len(relayClaimCalls) != 1 || relayClaimCalls[0] != relayHashToken(adminToken) {
			t.Fatalf("claim principal hash = %v, want [%s]", relayClaimCalls, relayHashToken(adminToken))
		}
	})

	t.Run("descriptor_plan_round_trips_through_the_typed_shape", func(t *testing.T) {
		// The typed projection: marshaling the api descriptor struct and
		// decoding it back into []store.PlanSpec rebuilds the seeded plan
		// exactly — the wire shape IS the store shape, body base64-decodes to
		// the original bytes. Nothing re-shaped handler-side.
		var typed relayClaimResponse
		blob, err := json.Marshal(relayClaimResponse{ID: 9, Purpose: "enrich", Plan: relaySeededPlan})
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		if err := json.Unmarshal(blob, &typed); err != nil {
			t.Fatalf("unmarshal: %v", err)
		}
		if !reflect.DeepEqual(typed.Plan, relaySeededPlan) {
			t.Fatalf("plan round trip mismatch:\n got %+v\nwant %+v", typed.Plan, relaySeededPlan)
		}
	})

	t.Run("live_lease_hides_the_row_from_the_next_principal", func(t *testing.T) {
		ctx := context.Background()
		st := openAPIStore(t)
		devices := pairing.NewService(st, nil)
		seedRelayJob(t, st)
		relayClaimCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, Pairing: devices, RelayClaim: relayClaimClosure(st)})

		// A second VALID credential (a paired device token) — the browse
		// group must admit it, and the claim must hide the row from it.
		req, err := devices.CreateRequest(ctx, "127.0.0.1:1")
		if err != nil {
			t.Fatalf("CreateRequest: %v", err)
		}
		if _, err := devices.Approve(ctx, req.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, req.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: %v/%+v", err, out)
		}

		first := doRequest(t, h, http.MethodPost, path, "", adminToken)
		defer first.Body.Close()
		if first.StatusCode != http.StatusOK {
			t.Fatalf("first claim status = %d, want %d", first.StatusCode, http.StatusOK)
		}
		// The device principal claims next: the lease is live, nothing is
		// claimable → 204 (single claimant by construction).
		second := doRequest(t, h, http.MethodPost, path, "", out.Token)
		defer second.Body.Close()
		if second.StatusCode != http.StatusNoContent {
			t.Fatalf("second claim status = %d, want %d", second.StatusCode, http.StatusNoContent)
		}
	})

	t.Run("nil_closure_is_503", func(t *testing.T) {
		st := openAPIStore(t)
		h := New(Deps{AdminToken: adminToken, Store: st})
		resp := doRequest(t, h, http.MethodPost, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unavailable" {
			t.Fatalf("error code = %q, want unavailable", eb.Error.Code)
		}
	})

	t.Run("closure_error_is_500_internal", func(t *testing.T) {
		st := openAPIStore(t)
		h := New(Deps{AdminToken: adminToken, Store: st, RelayClaim: func(context.Context, string) (store.RelayJob, bool, error) {
			return store.RelayJob{}, false, context.DeadlineExceeded
		}})
		resp := doRequest(t, h, http.MethodPost, path, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusInternalServerError)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "internal_error" {
			t.Fatalf("error code = %q, want internal_error", eb.Error.Code)
		}
	})

	t.Run("unauthenticated_is_401_and_never_claims", func(t *testing.T) {
		st := openAPIStore(t)
		seedRelayJob(t, st)
		relayClaimCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayClaim: relayClaimClosure(st)})

		resp := doRequest(t, h, http.MethodPost, path, "", "wrong-token")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusUnauthorized)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
		}
		if len(relayClaimCalls) != 0 {
			t.Fatalf("closure called %d times behind 401, want 0", len(relayClaimCalls))
		}
	})

	t.Run("device_token_reaches_the_handler", func(t *testing.T) {
		ctx := context.Background()
		st := openAPIStore(t)
		devices := pairing.NewService(st, nil)
		seedRelayJob(t, st)
		relayClaimCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, Pairing: devices, RelayClaim: relayClaimClosure(st)})

		req, err := devices.CreateRequest(ctx, "127.0.0.1:1")
		if err != nil {
			t.Fatalf("CreateRequest: %v", err)
		}
		if _, err := devices.Approve(ctx, req.ID); err != nil {
			t.Fatalf("Approve: %v", err)
		}
		out, err := devices.Wait(ctx, req.ID)
		if err != nil || out.Token == "" {
			t.Fatalf("Wait: %v/%+v", err, out)
		}
		// A paired device token is a browse-group principal: the handler runs
		// (200 with the descriptor), and the claim stamp carries the DEVICE
		// credential's hash — the same identity source as the admin token.
		resp := doRequest(t, h, http.MethodPost, path, "", out.Token)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if len(relayClaimCalls) != 1 || relayClaimCalls[0] != relayHashToken(out.Token) {
			t.Fatalf("claim principal hash = %v, want the device credential's hash", relayClaimCalls)
		}
	})

	t.Run("unknown_role_is_403_on_the_browse_gate", func(t *testing.T) {
		st := openAPIStore(t)
		relayClaimCalls = nil
		deps := Deps{AdminToken: adminToken, Store: st, RelayClaim: relayClaimClosure(st)}
		h := gatingRouter(deps, Role("superuser"))

		resp := doRequest(t, h, http.MethodPost, path, "", "no-authmw")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusForbidden {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusForbidden)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "forbidden" {
			t.Fatalf("error code = %q, want forbidden", eb.Error.Code)
		}
		if len(relayClaimCalls) != 0 {
			t.Fatalf("closure called %d times behind 403, want 0", len(relayClaimCalls))
		}
	})
}

// TestRelayClaimEmptyQueue pins the 204 half of the claim contract: nothing
// claimable — a truly empty queue, or a queue whose only row is claimed under
// a live lease — answers 204 with an EMPTY body, and no error envelope is
// ever written.
func TestRelayClaimEmptyQueue(t *testing.T) {
	cases := []struct {
		name string
		seed bool // seed one job and pre-claim it under a live lease
	}{
		{name: "empty_store_is_204", seed: false},
		{name: "live_lease_held_elsewhere_is_204", seed: true},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			st := openAPIStore(t)
			if tc.seed {
				seedRelayJob(t, st)
				now := time.Now()
				if _, found, err := st.ClaimOldestRelayJob(context.Background(), relayHashToken("someone-else"), now, now.Add(2*time.Minute)); err != nil || !found {
					t.Fatalf("pre-claim: found=%v err=%v", found, err)
				}
			}
			relayClaimCalls = nil
			h := New(Deps{AdminToken: adminToken, Store: st, RelayClaim: relayClaimClosure(st)})

			resp := doRequest(t, h, http.MethodPost, "/api/v1/relay/claim", "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusNoContent {
				t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNoContent)
			}
			if body, err := io.ReadAll(resp.Body); err != nil || len(body) != 0 {
				t.Fatalf("204 body = %q (err %v), want empty", body, err)
			}
		})
	}
}

// relayResultCall records one Deps.RelayResult invocation: the job id, the
// principal hash the handler derived, and the decoded result it handed over.
type relayResultCall struct {
	id     int64
	hash   string
	result store.RelayResult
}

// relayResultCalls is reset per subtest; every closure invocation appends.
var relayResultCalls []relayResultCall

// relayResultClosure is the cmd/mellifera closure's exact delegation shape
// (task 4.3): the enrich Relay.Ingest completes the claimed job through the
// store's guard — SAME principal hash, LIVE lease, one conditional UPDATE —
// picking done vs failed by the wire rule (error set → failed), and re-wraps
// the store's refusal ("enrich: relay ingest %d: %w" over the store's wrapped
// sql.ErrNoRows). The test builds it straight over the store seam, one hop
// down (the relayClaimClosure posture), and records every (id, hash, result).
func relayResultClosure(st *store.Store) func(context.Context, int64, string, store.RelayResult) error {
	return func(ctx context.Context, id int64, principalHash string, result store.RelayResult) error {
		relayResultCalls = append(relayResultCalls, relayResultCall{id: id, hash: principalHash, result: result})
		state := "done"
		if result.Error != "" {
			state = "failed"
		}
		if err := st.CompleteRelayJob(ctx, id, principalHash, state, result, time.Now()); err != nil {
			return fmt.Errorf("enrich: relay ingest %d: %w", id, err)
		}
		return nil
	}
}

// claimRelayFor claims the oldest seeded job for hashToken(credential)
// straight over the store seam with a live leaseUntil — the 4.1 claim
// mechanics one hop down, arranging the claimed state the result route
// guards against.
func claimRelayFor(t *testing.T, st *store.Store, credential string, leaseUntil time.Time) int64 {
	t.Helper()
	now := time.Now()
	job, found, err := st.ClaimOldestRelayJob(context.Background(), relayHashToken(credential), now, leaseUntil)
	if err != nil || !found {
		t.Fatalf("pre-claim: found=%v err=%v", found, err)
	}
	return job.ID
}

// relayDoneBody marshals a valid done-outcome payload — the exact shape 6.1's
// postResult posts, the body riding the base64 string encoding/json emits for
// []byte (the same encoding the plan's body used on the way out).
func relayDoneBody(t *testing.T) string {
	t.Helper()
	blob, err := json.Marshal(store.RelayResult{
		HTTPStatus: 200,
		Headers:    map[string]string{"Content-Type": "application/json"},
		Body:       []byte{0x00, 0xff, 0x7f},
	})
	if err != nil {
		t.Fatalf("marshal result body: %v", err)
	}
	return string(blob)
}

// resultPath builds the route for one job id.
func resultPath(id int64) string {
	return fmt.Sprintf("/api/v1/relay/%d/result", id)
}

// TestRelayResult pins the POST /api/v1/relay/{id}/result wire contract
// (client-relayed-fetch 4.2): a done outcome 204s with an empty body and hands
// the closure the base64-decoded result stamped with the SAME principal hash
// the claim used, a failed outcome rides the same route, a foreign principal /
// an expired lease / an unknown id are the closure's wrapped sql.ErrNoRows →
// 409 with the row untouched, a real closure failure is 500, malformed and
// empty bodies plus a non-integer id are 400, 503 when the closure is nil, and
// 401 with the closure never called when unauthenticated.
func TestRelayResult(t *testing.T) {
	t.Run("accepted_done_result_is_204_and_hands_the_closure_the_decoded_result", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		if body, err := io.ReadAll(resp.Body); err != nil || len(body) != 0 {
			t.Fatalf("204 body = %q (err %v), want empty", body, err)
		}
		if len(relayResultCalls) != 1 {
			t.Fatalf("closure calls = %d, want 1", len(relayResultCalls))
		}
		call := relayResultCalls[0]
		if call.id != wantID || call.hash != relayHashToken(adminToken) {
			t.Fatalf("closure args id/hash = %d/%q, want %d/%s", call.id, call.hash, wantID, relayHashToken(adminToken))
		}
		// The base64 body decoded into the bytes the store blob expects — the
		// same bytes the claim descriptor handed out on the way out.
		wantBody := []byte{0x00, 0xff, 0x7f}
		if call.result.HTTPStatus != 200 || !bytes.Equal(call.result.Body, wantBody) {
			t.Fatalf("result status/body = %d/%v, want 200/%v", call.result.HTTPStatus, call.result.Body, wantBody)
		}
		if call.result.Headers["Content-Type"] != "application/json" {
			t.Fatalf("result headers = %v, want the posted map verbatim", call.result.Headers)
		}
	})

	t.Run("failed_result_rides_the_same_route", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		// error set, response fields absent — the failed shape rides the same
		// route to the same 204 (D5 counts the round closure-side).
		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), `{"error":"upstream timeout"}`, adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNoContent)
		}
		if len(relayResultCalls) != 1 || relayResultCalls[0].result.Error != "upstream timeout" {
			t.Fatalf("closure calls = %+v, want one call carrying the error verbatim", relayResultCalls)
		}
	})

	t.Run("foreign_principal_is_409_and_leaves_the_row_untouched", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, "device-cred", time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusConflict {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusConflict)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "conflict" {
			t.Fatalf("error code = %q, want conflict", eb.Error.Code)
		}
		// The refusal left the claimed row untouched: the rightful principal
		// still completes it under its live lease.
		if err := st.CompleteRelayJob(context.Background(), wantID, relayHashToken("device-cred"), "done",
			store.RelayResult{HTTPStatus: 200}, time.Now()); err != nil {
			t.Fatalf("refused attempt mutated the row: %v", err)
		}
	})

	t.Run("expired_claim_is_409_even_for_its_own_principal", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(-time.Minute)) // the lease already lapsed
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusConflict {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusConflict)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "conflict" {
			t.Fatalf("error code = %q, want conflict", eb.Error.Code)
		}
	})

	t.Run("unknown_job_id_is_409", func(t *testing.T) {
		st := openAPIStore(t)
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(4242), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusConflict {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusConflict)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "conflict" {
			t.Fatalf("error code = %q, want conflict", eb.Error.Code)
		}
	})

	t.Run("over_cap_body_is_413_before_any_ingestion", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 64})

		// The payload is parseable JSON (the 6.1 shape) — only its SIZE trips
		// the cap: the 413 must fire before the closure is ever called.
		// (A body that is over-cap AND unparseable 400s — the scan error
		// surfaces first; the size guard is pinned by the parseable shape.)
		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusRequestEntityTooLarge {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusRequestEntityTooLarge)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "payload_too_large" {
			t.Fatalf("error code = %q, want payload_too_large", eb.Error.Code)
		}
		if len(relayResultCalls) != 0 {
			t.Fatalf("closure called %d times behind 413, want 0", len(relayResultCalls))
		}
	})

	t.Run("malformed_body_is_400", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), "{nope", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
		if len(relayResultCalls) != 0 {
			t.Fatalf("closure called %d times behind 400, want 0", len(relayResultCalls))
		}
	})

	t.Run("empty_body_is_400", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		// The outcome payload is not optional: an accepted zero result would
		// be a done row storing nothing.
		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
		if len(relayResultCalls) != 0 {
			t.Fatalf("closure called %d times behind 400, want 0", len(relayResultCalls))
		}
	})

	t.Run("non_integer_id_is_400", func(t *testing.T) {
		st := openAPIStore(t)
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, "/api/v1/relay/not-an-id/result", relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusBadRequest)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "bad_request" {
			t.Fatalf("error code = %q, want bad_request", eb.Error.Code)
		}
		if len(relayResultCalls) != 0 {
			t.Fatalf("closure called %d times behind 400, want 0", len(relayResultCalls))
		}
	})

	t.Run("nil_closure_is_503", func(t *testing.T) {
		st := openAPIStore(t)
		h := New(Deps{AdminToken: adminToken, Store: st, RelayMaxBody: 1 << 20})
		resp := doRequest(t, h, http.MethodPost, resultPath(1), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusServiceUnavailable {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusServiceUnavailable)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unavailable" {
			t.Fatalf("error code = %q, want unavailable", eb.Error.Code)
		}
	})

	t.Run("real_closure_failure_is_500_internal", func(t *testing.T) {
		st := openAPIStore(t)
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st,
			RelayResult: func(context.Context, int64, string, store.RelayResult) error {
				return context.DeadlineExceeded
			}, RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(7), relayDoneBody(t), adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusInternalServerError {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusInternalServerError)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "internal_error" {
			t.Fatalf("error code = %q, want internal_error", eb.Error.Code)
		}
	})

	t.Run("unauthenticated_is_401_and_never_ingests", func(t *testing.T) {
		st := openAPIStore(t)
		wantID := seedRelayJob(t, st)
		claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
		relayResultCalls = nil
		h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st), RelayMaxBody: 1 << 20})

		resp := doRequest(t, h, http.MethodPost, resultPath(wantID), relayDoneBody(t), "wrong-token")
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusUnauthorized {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusUnauthorized)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "unauthenticated" {
			t.Fatalf("error code = %q, want unauthenticated", eb.Error.Code)
		}
		if len(relayResultCalls) != 0 {
			t.Fatalf("closure called %d times behind 401, want 0", len(relayResultCalls))
		}
	})
}

// TestRelayResultBodyCap pins the Deps.RelayMaxBody boundary (4.2): the EXACT
// cap passes, one byte over is 413 with the closure never called — the same
// payload flipping on the Deps value alone proves the knob rides the
// composition root, not a handler constant.
func TestRelayResultBodyCap(t *testing.T) {
	body := `{"http_status":200,"body":"QUJD"}`
	cases := []struct {
		name       string
		capDelta   int64
		wantStatus int
		wantCalls  int
	}{
		{name: "at_cap_passes", capDelta: 0, wantStatus: http.StatusNoContent, wantCalls: 1},
		{name: "one_byte_over_is_413_before_ingestion", capDelta: -1, wantStatus: http.StatusRequestEntityTooLarge, wantCalls: 0},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			st := openAPIStore(t)
			wantID := seedRelayJob(t, st)
			claimRelayFor(t, st, adminToken, time.Now().Add(2*time.Minute))
			relayResultCalls = nil
			h := New(Deps{AdminToken: adminToken, Store: st, RelayResult: relayResultClosure(st),
				RelayMaxBody: int64(len(body)) + tc.capDelta})

			resp := doRequest(t, h, http.MethodPost, resultPath(wantID), body, adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != tc.wantStatus {
				t.Fatalf("status = %d, want %d", resp.StatusCode, tc.wantStatus)
			}
			if len(relayResultCalls) != tc.wantCalls {
				t.Fatalf("closure calls = %d, want %d", len(relayResultCalls), tc.wantCalls)
			}
		})
	}
}
